script:
(function () {
  'use strict';
  // Futures profit/loss and margin from user-entered contract specifications (no exchange specs built in).
  //   point value (dollars per 1.00 price move, per contract):
  //     tick mode:       tick value / tick size
  //     multiplier mode: contract size (multiplier)        -> tick value = multiplier x tick size
  //   direction d = +1 long, -1 short
  //   price move     = (exit - entry) x d               ticks = price move / tick size
  //   gross P/L      = price move x point value x contracts
  //   commissions    = commission per side x 2 x contracts
  //   net P/L        = gross P/L - commissions
  //   notional       = entry x point value x contracts
  //   margin % of notional = (initial margin per contract x contracts) / notional
  //   leverage       = notional / total margin          return on margin = net P/L / total margin
  //   breakeven exit = entry + d x (2 x commission per side) / point value
  // Verified (scratch Node test): long 2 contracts, entry 75.00, exit 77.50, tick 0.01 = $10 ->
  // 250 ticks, $2,500 per contract, $5,000 gross, $10 commissions ($2.50/side) -> $4,990 net;
  // notional $150,000, $12,000 margin = 8.00% of notional, 12.5x leverage, 41.58% return on margin,
  // breakeven exit 75.005. Same trade in multiplier mode (1,000) gives identical figures.
  // Index-style check: short 1 contract, entry 5,000.00, exit 4,980.00, tick 0.25 = $12.50 ->
  // 80 ticks, +$1,000 gross.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });

  function num(id) {
    var el = document.getElementById(id);
    var v = el ? parseFloat(el.value) : NaN;
    return isNaN(v) ? NaN : v;
  }
  function decimalsOf(id) {
    var el = document.getElementById(id);
    var s = el ? String(el.value || '') : '';
    var i = s.indexOf('.');
    return i < 0 ? 0 : Math.min(8, s.length - i - 1);
  }
  function fmt(v, dp) {
    if (!isFinite(v)) return '–';
    return v.toLocaleString('en-US', { minimumFractionDigits: dp, maximumFractionDigits: dp });
  }
  function signedMoney(v) {
    if (!isFinite(v)) return '–';
    if (Math.abs(v) < 0.005) v = 0;
    return (v < 0 ? '−' : '') + money.format(Math.abs(v));
  }

  function futures(o) {
    var pointValue = o.mode === 'tick' ? o.tickValue / o.tickSize : o.multiplier;
    var tickValue = pointValue * o.tickSize;
    var d = o.side === 'short' ? -1 : 1;
    var move = (o.exit - o.entry) * d;
    var ticks = move / o.tickSize;
    var perContract = move * pointValue;
    var gross = perContract * o.contracts;
    var commissions = o.commission * 2 * o.contracts;
    var net = gross - commissions;
    var notional = o.entry * pointValue * o.contracts;
    var margin = o.margin * o.contracts;
    return {
      pointValue: pointValue, tickValue: tickValue, move: move, ticks: ticks, perContract: perContract,
      gross: gross, commissions: commissions, net: net, notional: notional, margin: margin,
      marginPct: notional > 0 ? margin / notional * 100 : NaN,
      leverage: margin > 0 ? notional / margin : NaN,
      rom: margin > 0 ? net / margin * 100 : NaN,
      breakeven: o.entry + d * (2 * o.commission) / pointValue
    };
  }

  var OUT = ['futNet', 'futGross', 'futTicks', 'futRom', 'futMove', 'futPerContract', 'futTickVal', 'futPointValue',
             'futNotional', 'futMarginTotal', 'futMarginPct', 'futLeverage', 'futCommissions', 'futBreakeven'];

  function update() {
    var mode = document.getElementById('futMode').value;
    document.getElementById('futTickValueWrap').hidden = mode !== 'tick';
    document.getElementById('futMultiplierWrap').hidden = mode === 'tick';
    var o = {
      mode: mode, side: document.getElementById('futSide').value, contracts: num('futContracts'),
      entry: num('futEntry'), exit: num('futExit'), tickSize: num('futTickSize'), tickValue: num('futTickValue'),
      multiplier: num('futMultiplier'), margin: num('futMargin'), commission: num('futCommission')
    };
    if (isNaN(o.margin) && String(document.getElementById('futMargin').value).trim() === '') o.margin = 0;
    if (isNaN(o.commission) && String(document.getElementById('futCommission').value).trim() === '') o.commission = 0;
    var error = document.getElementById('futError');
    var note = document.getElementById('futTickNote');
    var msg = '';
    if ([o.contracts, o.entry, o.exit, o.tickSize].some(isNaN)) msg = 'Enter the number of contracts, entry and exit prices and the tick size.';
    else if (o.contracts < 1 || o.contracts !== Math.floor(o.contracts) || o.contracts > 100000) msg = 'Contracts must be a whole number from 1 to 100,000.';
    else if (o.entry <= 0 || o.exit < 0) msg = 'Enter an entry price above 0 and an exit price of 0 or more.';
    else if (!(o.tickSize > 0)) msg = 'Tick size must be above 0.';
    else if (mode === 'tick' && !(o.tickValue > 0)) msg = 'Tick value must be above 0.';
    else if (mode !== 'tick' && !(o.multiplier > 0)) msg = 'Contract size (multiplier) must be above 0.';
    else if (isNaN(o.margin) || o.margin < 0) msg = 'Margin per contract must be 0 or more.';
    else if (isNaN(o.commission) || o.commission < 0) msg = 'Commission must be 0 or more.';
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) {
      OUT.forEach(function (id) { document.getElementById(id).textContent = '–'; });
      note.hidden = true;
      return;
    }

    var r = futures(o);
    var dp = Math.max(2, decimalsOf('futEntry'), decimalsOf('futExit'), decimalsOf('futTickSize'));
    var whole = Math.abs(r.ticks - Math.round(r.ticks)) < 1e-6;
    note.hidden = whole;
    document.getElementById('futNet').textContent = signedMoney(r.net);
    document.getElementById('futGross').textContent = signedMoney(r.gross);
    document.getElementById('futTicks').textContent = fmt(r.ticks, whole ? 0 : 2);
    document.getElementById('futRom').textContent = isFinite(r.rom) ? r.rom.toFixed(2) + '%' : '–';
    document.getElementById('futMove').textContent = (r.move > 0 ? '+' : '') + fmt(r.move, dp);
    document.getElementById('futPerContract').textContent = signedMoney(r.perContract);
    document.getElementById('futTickVal').textContent = money.format(r.tickValue);
    document.getElementById('futPointValue').textContent = money.format(r.pointValue);
    document.getElementById('futNotional').textContent = money.format(r.notional);
    document.getElementById('futMarginTotal').textContent = money.format(r.margin);
    document.getElementById('futMarginPct').textContent = isFinite(r.marginPct) ? r.marginPct.toFixed(2) + '%' : '–';
    document.getElementById('futLeverage').textContent = isFinite(r.leverage) ? r.leverage.toFixed(1) + 'x' : '–';
    document.getElementById('futCommissions').textContent = money.format(r.commissions);
    document.getElementById('futBreakeven').textContent = r.breakeven < 0 ? 'Below 0' : fmt(r.breakeven, Math.min(8, dp + 2));
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('futForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
